      raise PetstoreClient.SerializationError,
        message: "Unknown enum value #{inspect(str)}; allowed values: #{inspect(allowed)}"
    end
  end

  def convert_to_type(data, return_type) do
    module = resolve_model_module(return_type)

    cond do
      function_exported?(module, :openapi_one_of, 0) or
          function_exported?(module, :openapi_any_of, 0) ->
        module.build(data)

      function_exported?(module, :openapi_types, 0) ->
        deserialize_model(data, module)

      function_exported?(module, :all_values, 0) ->
        atomize_enum(module, data)

      true ->
        data
    end
  end

  defp atomize_enum(_module, data) when is_atom(data), do: data

  defp atomize_enum(module, data) do
    # Deserialize by inverting the enum's value/1 mapping via from_value/1
    # rather than atomizing the raw wire value. The wire form may be
    # non-lowercase ("Available"), hyphenated ("on-hold"), or an integer for
    # an integer-backed enum — none of which equal the lowercased atom name,
    # so the previous String.to_atom + membership check silently failed for
    # every such enum. from_value/1 pattern-matches the declared wire values,
    # so it never mints an arbitrary atom from untrusted input (no atom-table
    # exhaustion) and raises only on genuine spec drift, matching the other SDKs.
    case module.from_value(data) do
      {:error, _} ->
        raise PetstoreClient.SerializationError,
              "Unknown enum value #{inspect(data)} for #{inspect(module)}; " <>
                "allowed values: #{inspect(module.all_values())}"

      atom ->
        atom
    end
  end

  # Returns true when at least one key in data matches a JSON key for the struct,
  # preventing a catch-all empty struct from winning over a better candidate.
  # Uses the attribute_map (JSON key names) when available so that camelCase
  # JSON keys are compared against camelCase attribute names, not snake_case field atoms.
  defp fields_overlap?(%{} = data, struct_instance) when is_struct(struct_instance) do
    module = struct_instance.__struct__

    json_keys =
      if function_exported?(module, :attribute_map, 0) do
        module.attribute_map() |> Map.values() |> MapSet.new()
      else
        struct_instance
        |> Map.from_struct()
        |> Map.keys()
        |> MapSet.new(&to_string/1)
      end

    data
    |> Map.keys()
    |> Enum.any?(fn k ->
      key_str = if is_atom(k), do: to_string(k), else: k
      MapSet.member?(json_keys, key_str)
    end)
  end

  defp fields_overlap?(_data, _result), do: true

  @doc false
  # Attempt to deserialize data against a list of candidate schemas, returning
  # the first successful result. Each candidate is an anonymous function that
  # accepts the raw JSON data and returns a deserialized value or raises on failure.
  # Candidates where no JSON key matches any struct field are skipped.
  @spec resolve_one_of(term(), [function()]) :: term()
  def resolve_one_of(data, candidates) do
    resolved =
      Enum.reduce_while(candidates, nil, fn candidate, _fallback ->
        try do
          result = candidate.(data)

          if fields_overlap?(data, result) do
            {:halt, result}
          else
            {:cont, nil}
          end
        rescue
          _ -> {:cont, nil}
        end
      end)

    if is_nil(resolved) do
      # A payload satisfying none of the declared variants is a contract
      # violation and must fail loudly rather than be silently dropped to nil.
      raise PetstoreClient.SchemaMismatchError,
        message: "No oneOf/anyOf variant matched the JSON"
    else
      resolved
    end
  end

  @doc false
  # Attempt to deserialize data against a list of candidate schemas using
  # anyOf semantics. Delegates to `resolve_one_of/2`.
  @spec resolve_any_of(term(), [function()]) :: term()
  def resolve_any_of(data, candidates) do
    resolve_one_of(data, candidates)
  end

  @doc """
  Attempt to deserialize data as the given type for oneOf/anyOf resolution.
  Uses the try-deserialize-and-catch pattern by delegating to `convert_to_type/2`.
  """
  def find_and_cast_into_type(_type_name, data) when is_nil(data), do: nil

  def find_and_cast_into_type(type_name, data) do
    type_str = to_string(type_name)
    result = convert_to_type(data, type_str)

    if is_nil(result) do
      raise PetstoreClient.SchemaMismatchError,
        message: "#{inspect(data)} doesn't match the #{type_str} type"
    else
      result
    end
  end

  defp deserialize_model(data, module) when is_map(data) do
    data = Map.new(data, fn {k, v} -> {to_string(k), v} end)
    openapi_types = module.openapi_types()
    attr_map = module.attribute_map()

    # Divergence #10: a required, non-nullable property that is absent or
    # explicitly null in the wire payload is a contract violation. Fail
    # loudly with a SerializationError instead of silently building a
    # partial struct (which would surface as a confusing nil far from the
    # actual fault). Aligns Elixir with Go/PHP/Kotlin/Swift/Rust, which
    # all reject a missing/null required field on deserialize. Optional and
    # required-but-nullable fields are untouched.
    assert_required_present(data, module)

    # Gap AX.1 / parity with Go: when the schema declares
    # unevaluatedProperties:false (the codegen emits from_map_strict/1 only
    # for such models), reject any wire key not declared by the model instead
    # of silently dropping it, matching the other SDKs.
    if function_exported?(module, :from_map_strict, 1) do
      declared = attr_map |> Map.values() |> MapSet.new()

      Enum.each(Map.keys(data), fn key ->
        unless MapSet.member?(declared, key) do
          raise PetstoreClient.SerializationError,
            message:
              "Unknown property '#{key}' on #{inspect(module)} (unevaluatedProperties:false)"
        end
      end)
    end

    transformed =
      Enum.reduce(openapi_types, %{}, fn {attr, type}, acc ->
        json_key = Map.get(attr_map, attr)

        if Map.has_key?(data, json_key) do
          value = Map.get(data, json_key)

          converted =
            if is_nil(value) do
              nil
            else
              convert_to_type(value, to_string(type))
            end

          Map.put(acc, attr, converted)
        else
          acc
        end
      end)

    transformed = capture_additional_properties(transformed, data, module, attr_map)

    struct(module, transformed)
  end

  # 2.19 additionalProperties round-trip: when the model declares
  # `additional_properties/0 == true`, undeclared wire keys are not discarded
  # but captured into the struct's `additional_properties` map so they survive
  # a deserialize/serialize round-trip. Values are type-converted through
  # `additional_properties_type/0` when the model declares a value type.
  # Matches the round-trip behaviour of Python/Go/Java/Node/etc.
  defp capture_additional_properties(transformed, data, module, attr_map) do
    if function_exported?(module, :additional_properties, 0) and module.additional_properties() do
      declared = attr_map |> Map.values() |> MapSet.new()

      value_type =
        if function_exported?(module, :additional_properties_type, 0) do
          module.additional_properties_type()
        else
          nil
        end

      extras =
        data
        |> Enum.reject(fn {key, _v} -> MapSet.member?(declared, key) end)
        |> Map.new(fn {key, value} ->
          converted =
            if is_nil(value) or is_nil(value_type) do
              value
            else
              convert_to_type(value, to_string(value_type))
            end

          {key, converted}
        end)

      Map.put(transformed, :additional_properties, extras)
    else
      transformed
    end
  end

  defp deserialize_model(_data, _module), do: nil

  # Raises SerializationError if any required, non-nullable property declared
  # by `module.required_fields/0` is missing from, or explicitly null in, the
  # already-stringified wire map. See the call site in `deserialize_model/2`.
  defp assert_required_present(data, module) when is_map(data) do
    if function_exported?(module, :required_fields, 0) do
      Enum.each(module.required_fields(), fn json_key ->
        cond do
          not Map.has_key?(data, json_key) ->
            raise PetstoreClient.SerializationError,
              message: "Missing required field '#{json_key}' for #{inspect(module)}"

          is_nil(Map.get(data, json_key)) ->
            raise PetstoreClient.SerializationError,
              message: "Required field '#{json_key}' for #{inspect(module)} must not be null"

          true ->
            :ok
        end
      end)
    end

    :ok
  end

  @doc """
  Format a `Duration.t()` as a `google.protobuf.Duration` protobuf-JSON
  string.

  Emits a decimal second count suffixed with `s`. Fractional seconds, when
  present, use 3, 6, or 9 digits — the smallest grouping that preserves every
  non-zero microsecond digit (e.g. `"3600s"`, `"1.500s"`,
  `"-1.500000s"`). The duration is reduced to a signed total of microseconds
  so the sign stays coherent across mixed-sign components; `Duration`'s
  resolution caps fractional precision at microseconds.
  """
  @spec format_protobuf_duration(Duration.t()) :: String.t()
  def format_protobuf_duration(%Duration{} = duration) do
    total_micros = duration_to_microseconds(duration)
    sign = if total_micros < 0, do: "-", else: ""
    abs_micros = abs(total_micros)
    secs = div(abs_micros, 1_000_000)
    micros = rem(abs_micros, 1_000_000)

    if micros == 0 do
      "#{sign}#{secs}s"
    else
      nanos = micros * 1000
      frac = String.pad_leading(Integer.to_string(nanos), 9, "0")
      kept = duration_fraction_digits(frac)
      "#{sign}#{secs}.#{String.slice(frac, 0, kept)}s"
    end
  end

  @doc """
  Parse a `google.protobuf.Duration` protobuf-JSON string into a
  `Duration.t()`.

  Accepts the grammar `-?\\d+(\\.\\d{1,9})?s`. The fractional part is
  right-padded to nine digits to recover nanoseconds; sub-microsecond digits
  are truncated to fit `Duration`'s microsecond resolution. Returns
  `{:ok, Duration.t()}` on success or `:error` on malformed input.
  """
  @spec parse_protobuf_duration(String.t()) :: {:ok, Duration.t()} | :error
  def parse_protobuf_duration(text) do
    case Regex.run(~r/^(-?)(\d+)(?:\.(\d{1,9}))?s$/, text) do
      [_, sign, secs_str, frac_str] ->
        build_protobuf_duration(sign, secs_str, frac_str)

      [_, sign, secs_str] ->
        build_protobuf_duration(sign, secs_str, "")

      _ ->
        :error
    end
  end

  defp build_protobuf_duration(sign, secs_str, frac_str) do
    secs = String.to_integer(secs_str)

    micros =
      case frac_str do
        "" -> 0
        _ -> div(String.to_integer(String.pad_trailing(frac_str, 9, "0")), 1000)
      end

    total_micros = secs * 1_000_000 + micros
    total_micros = if sign == "-", do: -total_micros, else: total_micros

    {:ok,
     %Duration{
       second: div(total_micros, 1_000_000),
       microsecond: {rem(total_micros, 1_000_000), 6}
     }}
  end

  defp duration_to_microseconds(%Duration{} = d) do
    {micros, _precision} = d.microsecond

    (d.year * 31_556_952 + d.month * 2_629_746 + d.week * 604_800 + d.day * 86_400 +
       d.hour * 3600 + d.minute * 60 + d.second) * 1_000_000 + micros
  end

  defp duration_fraction_digits(frac) do
    cond do
      String.ends_with?(frac, "000000") -> 3
      String.ends_with?(frac, "000") -> 6
      true -> 9
    end
  end

  @doc false
  # Resolves a type-name string to its generated module atom, ensuring the
  # module is loaded so `function_exported?/3` introspection is reliable.
  # Public so ValueSerializer can resolve enum modules for wire-value mapping.
  def resolve_model_module(type_name) do
    module =
      try do
        Module.concat([PetstoreClient, Models, type_name])
      rescue
        _ -> Module.concat([PetstoreClient, type_name])
      end

    # Elixir 1.19 loads modules lazily: a freshly-referenced module atom is
    # not in memory until something forces it, and `function_exported?/3`
    # reports `false` for any not-yet-loaded module. The `convert_to_type/2`
    # fallback introspects this module with `function_exported?/3` to pick the
    # oneOf/anyOf/struct/enum branch, so it must be loaded first or every
    # composed/struct type silently falls through to the raw-map branch.
    Code.ensure_loaded(module)
    module
  end
end
